#include "kernel/codecapps/archive/archive.h"
#include "kernel/codecapps/archive/selftest_blobs.h"
#include "kernel/codecapps/arena.h"
#include "kernel/codecapps/avi.h"
#include "kernel/codecapps/image/jpeg_selftest_blob.h"
#include "kernel/codecapps/registry.h"
#include "kernel/serial.hpp"

// CodecsApps archive selftest (issue #180). All fixtures are embedded
// byte vectors generated by tools/mkarchive_selftest.py: a real
// zipfile-produced ZIP (deflated + stored + directory entries), a
// tarfile-produced ustar TAR, a gzip.compress member, and a runtime-built
// AVI/MJPEG container around the JPEG selftest vector.
// Serial markers:
//   zip entries=N   zip extract=ok   tar entries=N
//   gzip decode=ok  gzip encode=ok   avi demux=ok frames=N
//   codec archive=ok

namespace hype::codec::archive {

    namespace {

        hcpp::u8 at_arena[32768];
        hcpp::u8 at_extract[4096];
        hcpp::u8 at_gz[4096];
        hcpp::u8 at_gz_rt[4096];
        hcpp::u8 at_frame[8192];
        ArchiveEntry at_entries[16];
        hcpp::u8 at_avi[4096];

        bool bytes_equal(const hcpp::u8 *a, const hcpp::u8 *b, hcpp::size_t n) noexcept {
            for (hcpp::size_t i = 0; i < n; ++i)
                if (a[i] != b[i]) return false;
            return true;
        }

        void wr16(hcpp::u8 *p, hcpp::u16 v) noexcept {
            p[0] = static_cast<hcpp::u8>(v & 0xFF);
            p[1] = static_cast<hcpp::u8>(v >> 8);
        }

        void wr32(hcpp::u8 *p, hcpp::u32 v) noexcept {
            p[0] = static_cast<hcpp::u8>(v & 0xFF);
            p[1] = static_cast<hcpp::u8>((v >> 8) & 0xFF);
            p[2] = static_cast<hcpp::u8>((v >> 16) & 0xFF);
            p[3] = static_cast<hcpp::u8>(v >> 24);
        }

        void tag4(hcpp::u8 *p, char a, char b, char c, char d) noexcept {
            p[0] = static_cast<hcpp::u8>(a);
            p[1] = static_cast<hcpp::u8>(b);
            p[2] = static_cast<hcpp::u8>(c);
            p[3] = static_cast<hcpp::u8>(d);
        }

        bool test_zip(Arena &arena) noexcept {
            using namespace selftest_blobs;
            if (codec_probe(zip_blob, sizeof(zip_blob)) != CodecId::Zip) return false;
            ArchiveList list{at_entries, sizeof(at_entries) / sizeof(at_entries[0]), 0};
            if (codec_decode(CodecId::Zip, zip_blob, sizeof(zip_blob), &list, arena) !=
                CodecStatus::Ok)
                return false;
            serial::write("zip entries=");
            serial::write_dec32(static_cast<hcpp::u32>(list.count));
            serial::write("\r\n");
            if (list.count != 3) return false;
            const ArchiveEntry *hello = archive_find(list, "hello.txt");
            const ArchiveEntry *data = archive_find(list, "data.bin");
            const ArchiveEntry *dir = archive_find(list, "docs/");
            if (hello == nullptr || data == nullptr || dir == nullptr) return false;
            if ((dir->flags & archive_entry_dir) == 0) return false;
            hcpp::size_t out = 0;
            bool ok = hello->method == 8 && hello->size == sizeof(hello_payload) &&
                      zip_extract(zip_blob, sizeof(zip_blob), *hello, at_extract,
                                  sizeof(at_extract), out) == CodecStatus::Ok &&
                      out == sizeof(hello_payload) &&
                      bytes_equal(at_extract, hello_payload, out);
            ok = ok && data->method == 0 &&
                 zip_extract(zip_blob, sizeof(zip_blob), *data, at_extract,
                             sizeof(at_extract), out) == CodecStatus::Ok &&
                 out == 64;
            for (hcpp::size_t i = 0; ok && i < 64; ++i)
                if (at_extract[i] != static_cast<hcpp::u8>(i)) ok = false;
            serial::write("zip extract=");
            serial::write_line(ok ? "ok" : "fail");
            return ok;
        }

        bool test_tar(Arena &arena) noexcept {
            using namespace selftest_blobs;
            if (codec_probe(tar_blob, sizeof(tar_blob)) != CodecId::Tar) return false;
            ArchiveList list{at_entries, sizeof(at_entries) / sizeof(at_entries[0]), 0};
            if (codec_decode(CodecId::Tar, tar_blob, sizeof(tar_blob), &list, arena) !=
                CodecStatus::Ok)
                return false;
            serial::write("tar entries=");
            serial::write_dec32(static_cast<hcpp::u32>(list.count));
            serial::write("\r\n");
            const ArchiveEntry *hello = archive_find(list, "hello.txt");
            const ArchiveEntry *data = archive_find(list, "data.bin");
            return list.count == 2 && hello != nullptr && data != nullptr &&
                   hello->size == sizeof(hello_payload) &&
                   hello->offset + hello->size <= sizeof(tar_blob) &&
                   bytes_equal(tar_blob + hello->offset, hello_payload,
                               hello->size) &&
                   data->size == 64 && data->offset + 64 <= sizeof(tar_blob) &&
                   tar_blob[data->offset] == 0 && tar_blob[data->offset + 63] == 63;
        }

        bool test_gzip(Arena &arena) noexcept {
            using namespace selftest_blobs;
            if (codec_probe(gzip_blob, sizeof(gzip_blob)) != CodecId::Gzip) return false;
            BlobOut out{at_gz, sizeof(at_gz), 0};
            bool ok = codec_decode(CodecId::Gzip, gzip_blob, sizeof(gzip_blob), &out,
                                   arena) == CodecStatus::Ok &&
                      out.size == sizeof(hello_payload) &&
                      bytes_equal(out.data, hello_payload, out.size);
            serial::write("gzip decode=");
            serial::write_line(ok ? "ok" : "fail");
            if (!ok) return false;
            BlobOut in{const_cast<hcpp::u8 *>(hello_payload), sizeof(hello_payload),
                       sizeof(hello_payload)};
            hcpp::size_t written = 0;
            ok = codec_encode(CodecId::Gzip, &in, at_gz_rt, sizeof(at_gz_rt), written,
                              arena) == CodecStatus::Ok &&
                 written != 0;
            out = BlobOut{at_gz, sizeof(at_gz), 0};
            ok = ok && codec_decode(CodecId::Gzip, at_gz_rt, written, &out, arena) ==
                           CodecStatus::Ok &&
                 out.size == sizeof(hello_payload) &&
                 bytes_equal(out.data, hello_payload, out.size);
            serial::write("gzip encode=");
            serial::write_line(ok ? "ok" : "fail");
            return ok;
        }

        hcpp::size_t avi_build() noexcept {
            // Minimal RIFF AVI: hdrl {avih, strl{strh vids/MJPG, strf BIH}} +
            // movi {00dc jpeg, 00dc jpeg} — mirrors videocoretest's writer.
            const hcpp::size_t jlen = sizeof(jpeg_selftest_blob);
            const hcpp::size_t jpad = jlen & 1;
            hcpp::size_t p = 0;
            tag4(at_avi + p, 'R', 'I', 'F', 'F');
            wr32(at_avi + p + 4, 0);
            tag4(at_avi + p + 8, 'A', 'V', 'I', ' ');
            p += 12;
            const hcpp::size_t hdrl = p;
            tag4(at_avi + p, 'L', 'I', 'S', 'T');
            wr32(at_avi + p + 4, 0);
            tag4(at_avi + p + 8, 'h', 'd', 'r', 'l');
            p += 12;
            tag4(at_avi + p, 'a', 'v', 'i', 'h');
            wr32(at_avi + p + 4, 56);
            for (hcpp::u32 k = 0; k < 56; ++k) at_avi[p + 8 + k] = 0;
            wr32(at_avi + p + 8, 33333);   // dwMicroSecPerFrame
            wr32(at_avi + p + 8 + 32, 2);  // dwTotalFrames
            p += 64;
            const hcpp::size_t strl = p;
            tag4(at_avi + p, 'L', 'I', 'S', 'T');
            wr32(at_avi + p + 4, 0);
            tag4(at_avi + p + 8, 's', 't', 'r', 'l');
            p += 12;
            tag4(at_avi + p, 's', 't', 'r', 'h');
            wr32(at_avi + p + 4, 56);
            tag4(at_avi + p + 8, 'v', 'i', 'd', 's');
            tag4(at_avi + p + 12, 'M', 'J', 'P', 'G');
            for (hcpp::u32 k = 16; k < 56; ++k) at_avi[p + 8 + k] = 0;
            wr32(at_avi + p + 8 + 32, 1);   // dwScale
            wr32(at_avi + p + 8 + 36, 30);  // dwRate
            wr32(at_avi + p + 8 + 40, 2);   // dwLength
            p += 64;
            tag4(at_avi + p, 's', 't', 'r', 'f');
            wr32(at_avi + p + 4, 40);
            wr32(at_avi + p + 8, 40);                    // biSize
            wr32(at_avi + p + 12, JPEG_SELFTEST_WIDTH);  // biWidth
            wr32(at_avi + p + 16, JPEG_SELFTEST_HEIGHT); // biHeight
            wr16(at_avi + p + 20, 1);                    // biPlanes
            wr16(at_avi + p + 22, 24);                   // biBitCount
            tag4(at_avi + p + 24, 'M', 'J', 'P', 'G');   // biCompression
            for (hcpp::u32 k = 28; k < 40; ++k) at_avi[p + 8 + k] = 0;
            p += 48;
            wr32(at_avi + strl + 4, static_cast<hcpp::u32>(p - strl - 8));
            wr32(at_avi + hdrl + 4, static_cast<hcpp::u32>(p - hdrl - 8));
            const hcpp::size_t movi = p;
            tag4(at_avi + p, 'L', 'I', 'S', 'T');
            wr32(at_avi + p + 4, 0);
            tag4(at_avi + p + 8, 'm', 'o', 'v', 'i');
            p += 12;
            for (hcpp::u32 f = 0; f < 2; ++f) {
                tag4(at_avi + p, '0', '0', 'd', 'c');
                wr32(at_avi + p + 4, static_cast<hcpp::u32>(jlen));
                p += 8;
                for (hcpp::size_t k = 0; k < jlen; ++k)
                    at_avi[p + k] = jpeg_selftest_blob[k];
                p += jlen;
                if (jpad) at_avi[p++] = 0;
            }
            wr32(at_avi + movi + 4, static_cast<hcpp::u32>(p - movi - 8));
            wr32(at_avi + 4, static_cast<hcpp::u32>(p - 8));
            return p;
        }

        bool test_avi(Arena &arena) noexcept {
            const hcpp::size_t n = avi_build();
            if (codec_probe(at_avi, n) != CodecId::Avi) return false;
            const hcpp::u32 frames = avi_frame_count(at_avi, n);
            FrameBuf frame{};
            frame.data = at_frame;
            frame.capacity = sizeof(at_frame);
            const bool ok = frames == 2 &&
                            codec_decode(CodecId::Avi, at_avi, n, &frame, arena) ==
                                CodecStatus::Ok &&
                            frame.width == JPEG_SELFTEST_WIDTH &&
                            frame.height == JPEG_SELFTEST_HEIGHT &&
                            frame.size == JPEG_SELFTEST_WIDTH * JPEG_SELFTEST_HEIGHT * 4;
            serial::write("avi demux=");
            serial::write(ok ? "ok" : "fail");
            serial::write(" frames=");
            serial::write_dec32(frames);
            serial::write("\r\n");
            return ok;
        }

    }  // namespace

    bool archive_selftest() noexcept {
        Arena arena{at_arena, sizeof(at_arena), 0};
        bool ok = true;
        ok = test_zip(arena) && ok;
        ok = test_tar(arena) && ok;
        ok = test_gzip(arena) && ok;
        ok = test_avi(arena) && ok;
        serial::write("codec archive=");
        serial::write_line(ok ? "ok" : "fail");
        return ok;
    }

}  // namespace hype::codec::archive
